async () => {
  const renderer = await import('./src/renderer.js');
  let acknowledgements = 0;
  let routes = 0;
  const send = (key, repeat = false) => {
    const event = new KeyboardEvent('keydown', { key, repeat, bubbles: true, cancelable: true });
    document.dispatchEvent(event);
    return event;
  };
  const assert = (condition, message) => { if (!condition) throw new Error(message); };
  renderer.showContinue('FIRST HOLD', () => {
    acknowledgements++;
    window.setTimeout(() => renderer.showContinue('SECOND HOLD', () => { acknowledgements++; }), 30);
  });
  send('Enter');
  assert(acknowledgements === 1, 'Fresh Enter must acknowledge the first hold');
  await new Promise(resolve => window.setTimeout(resolve, 80));
  for (const key of ['Enter', ' ']) {
    assert(send(key, true).defaultPrevented, 'Repeated activation must cancel the native button action');
  }
  assert(acknowledgements === 1, 'One held press must not consume a later control');
  send(' ');
  assert(acknowledgements === 2, 'Fresh Space must acknowledge the second hold');
  renderer.showOptions([{ label: 'REGRESSION ROUTE', compliance_delta: 1 }], () => { routes++; });
  send('1');
  assert(send('Enter', true).defaultPrevented, 'Repeated Enter must not submit a selected route');
  assert(routes === 0, 'A selected route needs a fresh submission');
  send('Enter');
  assert(routes === 1, 'Fresh Enter must submit the selected route');
  renderer.clearOptions();
  document.getElementById('power-btn').focus();
  for (const key of ['Enter', ' ']) {
    assert(send(key, true).defaultPrevented, 'Repeat must not leak to the focused power switch between controls');
  }
}
